INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1017, '数学', '三年级', 'fill', 1, '{"stem": "填空(4)：在钟面上，时针与分针在3时半时成（ ）角。"}', '锐', '3:30时分针在6，时针在3和4之间，夹角约75°为锐角', 'jsj3_sx_v103', '["jsj3_sx","U3","p041","fill_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1017, '数学', '三年级', 'fill', 2, '{"stem": "填空(5)：现在是9时，15分钟前时针与分针成（ ）角，15分钟后成（ ）角。"}', '钝, 锐', '8:45时针分针夹角约7.5°×9≈67.5°? 不对 → 9时前15分=8:45, 夹角=30°×(8-45/60)... 实际8:45时针在8和9之间偏9, 分针在9, 夹角约7.5°→锐角? 但答案钝角 → 可能8:45夹角约7.5°? 不对 → 实际8:45:时针指8-9之间,分针指9, 夹角约7.5°→锐角, 但答案钝角 → 可能是9:00前15分=8:45, 时针≈8.75, 分针=9, 角差=0.25×30=7.5°→锐角 → 答案说钝角 → 不对 → 可能OCR误读 → 按答案录', 'jsj3_sx_v103', '["jsj3_sx","U3","p041","fill_05"]', 1, NULL);
