INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1018, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：图中有（ ）个直角三角形，有（ ）个锐角三角形，有（ ）个钝角三角形。（10分）"}', '12, 2, 2', '直角三角形：4×2=8个小+4个大=12; 锐角三角形：左右各1个=2; 钝角三角形：上下各1个=2', 'jsj3_sx_v103', '["jsj3_sx","U3","p043","think_01"]', 1, NULL);